//260710 hbk 버전 관리 단일 소스. AssemblyVersion/AssemblyFileVersion/RecipeFileHelper.GetVersion() 이
//모두 이 파일의 VersionDefine.VERSION 상수 하나만 참조하도록 일원화한다.
//버전을 올릴 때는 VERSION/BUILD_DATE 를 수정하고, 그 위에 [Version] 항목을 새로 하나 더 쌓는다(기존 항목은 지우지 않음).
using System;

namespace ReringProject
{
    //260710 hbk 클래스 위에 [Version(...)] 을 여러 개 쌓아 changelog 를 코드로 남기기 위한 어트리뷰트
    [AttributeUsage(AttributeTargets.Class, AllowMultiple = true)]
    public class VersionAttribute : Attribute
    {
        public string Number { get; set; }
        public string Date { get; set; }
        public string Change { get; set; }
    }

    //260710 hbk 시작 버전. 기존엔 AssemblyVersion 24.11.6.1 / AssemblyFileVersion 24.12.10.02 가 서로 불일치했음
    [Version(
        Number = "1.4.0.0",
        Date = "2026-07-10",
        Change = "버전 관리를 VersionDefine.cs 로 일원화(AssemblyVersion/AssemblyFileVersion/RecipeFileHelper.GetVersion 이 모두 단일 상수 참조. 기존엔 AssemblyVersion 24.11.6.1 과 AssemblyFileVersion 24.12.10.02 가 불일치). 죽은 코드 스윕 2,310줄 삭제(csproj 미등록 파일 6개 + 참조 0 메서드/필드 + 주석블록/미사용 using). skip-사유 문자열(DATUM_FAIL/ALIGN_FAIL/NO_IMAGE)을 SkipReason 상수로 통합해 오타 시 silent 오동작 제거."
    )]
    [Version(
        Number = "1.5.0.0",
        Date = "2026-07-14",
        Change = "Datum 전용 per-channel 조명 신설(Ring6+Bar4+Back+Ring7+Coax, ShotConfig 와 동일 명명) — 티칭 Grab(GrabAndDisplay 신규 오버로드)과 런타임 DatumPhase(Action_FAIMeasurement) 양쪽에 적용 배선, PropertyGrid Light 탭 분리(Category=\"Light|...\" 규칙으로 Datum 탭과 별도 탭). " +
                 "조명 컨트롤러 미연결 시 앱 초기화 차단하던 결함 수정(LightHandler Initialize 결과를 로그로만 남기고 진행) + MIL 카메라 기본 에러 팝업 비활성화, MdigGrab 실패 감지, 실측 해상도/FPS 반영, Grab Direction Flip X/Y 추가. " +
                 "ShotConfig/DatumConfig Light 탭 밝기 슬라이더 전체(Ring/Bar/Back/Ring7/Coax)에 PropertyChanged 발화 추가 — 드래그해도 숫자칸이 안 바뀌던 결함 수정. " +
                 "FAI ROI 이동/리사이즈/삭제 write-back 을 Shot 컨텍스트 기반으로 재구현(여러 Shot 에 동일 이름 FAI 존재 시 엉뚱한 객체에 쓰던 결함) + 측정 Point ROI(EdgeToLineDistance 등 9종) write-back 신규 구현(기존엔 무동작). " +
                 "light.ini 를 물리채널↔논리이름 매핑(ChannelNames) 재배선 가능하도록 확장 + 저장 경로를 bin 폴더에서 D:\\Data\\Light 로 이전(재빌드/재배포 시에도 설정 보존). " +
                 "LightGroup 이 채널 재배선을 반영 못 하던 결함(RebindChannels 신설, 이름 소실 시 그룹 아이템 제거) 및 조명 명령이 실제 반영되기 전에 grab 하던 타이밍 결함(WaitForPendingWrites) 수정 — 재배선 후 존재하지 않는 이름의 그룹이 다른 채널의 물리 위치를 침범해 조명이 켜지자마자 꺼지던 버그 포함."
    )]
    [Version(
        Number = "1.6.0.0",
        Date = "2026-07-15",
        Change = "수동/오프라인 검사 모드 신설(OfflineInspectMode 플래그) — Z 모터 없는 수동 지그에서 사람이 datum/shot Z 를 맞춰 확보한 저장 이미지로 검사. 노드별 '검사Grab' 버튼(라이브 grab → <ImageSavePath>\\OfflineInspect\\<recipe>\\ 에 png 저장 → 노드 SimulImagePath/TeachingImagePath 반영, 1클릭). 플래그 ON 이면 실HW 빌드(Debug|x64 SIMUL_MODE off)에서도 EStep.Grab/DatumPhase 가 라이브 grab 대신 저장 이미지 로드(SIMUL 로드 경로와 공유 헬퍼 LoadShotInspectionImage/LoadDatumImageFromPath). 각 이미지가 이미 올바른 Z(초점)라 공유 datum 정합 성립 — 라이브 grab 이 shot 마다 datum transform 을 재계산하며 무너지던 문제 우회. " +
                 "Datum 재-앵커(마스터 샘플 교체) 신설 — 옛 datum 으로 새 마스터를 Find 한 강체 변환 T 를 모든 참조 측정 ROI + FAI rect + datum 검색 ROI 에 일괄 적용해 재작업 없이 이전. 미리보기(원본 불변, 노란 오버레이) + 확인 모달 + 레시피 자동 백업(.reanchor_bak_*) + Find 실패 시 무변경 중단 안전장치. 중심=AffineTransPoint2d(T), 각도=+Atan2(-T[1],T[0]), 길이/반경/공칭/공차/보정계수 불변. " +
                 "측정별 보정계수(MeasCorrectionFactor) 신설 — vision↔현미경 값 매칭용 곱셈 보정(EvaluateJudgement 에서 적용), 각도 측정(LineToLineAngle/EdgeToLineAngle/CompoundAngle)은 AppliesCorrectionFactor=false 로 제외. INI 키 부재 시 Load 오버라이드로 1.0 복원(0 로드 시 전 측정 0 되던 하위호환 결함 방지). 단 운용 결정으로 이 측정별 계수는 PropertyGrid 에서 숨김([Browsable(false)]) — 보정은 Shot 계수(CorrectionFactor) 단일 레이어로 관리하고 안 맞는 포인트는 별도 Shot 으로 분리(값/로직 보존, 전부 1.0=무보정이라 측정값 변화 0, [Browsable(false)] 제거로 재노출 가능). " +
                 "datum 보정 하 WYSIWYG ROI 편집 — 보정된 화면 위치로 ROI 드래그 시 역변환으로 raw 기준좌표에 저장. 선택 측정 ROI 파랑 강조 + 주황 대형 이름 라벨로 편집 대상 식별. FAI 노드/측정 노드가 동일(보정된) 위치에 ROI 표시. " +
                 "ROI 편집 결함 수정: Edit 확대 상태에서 ROI 드래그 후 놓으면 사라지던 것(확대/뷰 상태 보존) + 같은 shot 내 측정 노드 이동 시 줌 초기화되던 것 보존 + ArcLineIntersect 등 다중 ROI(4개) 측정에서 서브 ROI 개별 드래그 불가(HitTest 전체 ROI fallback)하던 것 수정. " +
                 "Test Find 게이트 수정 — 패턴정렬(.shm 모델) datum 도 Find 허용(라인핏 datum 만 허용하던 게이트 확장). " +
                 "Grab 데드락 수정 — GrabAndDisplay/GrabSaveAndDisplay 가 mDrawInterlock(그리기 락)을 쥔 채 WaitForPendingWrites(≤500ms)+ExecuteOnUi(Dispatcher.Invoke)로 UI 를 기다려, grab 도중 트리/Shot 이동 시 UI 스레드가 같은 락을 요청하며 영구 데드락(백그라운드↔UI 상호대기). 락을 grab 구간에만 한정하고 저장/표시는 락 해제 후 수행하도록 재구성(검사이미지 저장은 락 안 CopyImage 사본으로 크로스스레드 분리). grab 예외 시 GrabTask 가 non-null 로 남아 이후 grab 이 재시작까지 막히던 결함도 try/finally 로 정리."
    )]
    [Version(
        Number = "1.6.1.0",
        Date = "2026-07-16",
        Change = "자동 검사 사이클(Action_FAIMeasurement)에 조명 반영 대기(WaitForPendingWrites) 미배선 결함 수정. 1.5.0.0 changelog 는 이 타이밍 결함을 수정했다고 기록했으나 실제 배선 범위는 MainView.xaml.cs 수동 Grab 버튼 3곳뿐이었고, 정작 매 생산 사이클마다 도는 자동 검사 흐름(EStep.DatumPhase→datum grab, EStep.DatumPhase 종료 Shot 조명 복귀→EStep.Grab)에는 대기가 전혀 없어 조명이 큐잉된 직후(실제 시리얼 전송 완료 전) 즉시 촬영될 수 있었다(리포지토리 전수 grep 으로 확인, 자동 사이클 경로 0건). 조명 전환이 심하면 datum 검출 실패로 로그와 함께 드러나지만, 전환이 부분적이면 검출은 성공하되 에지 서브픽셀 위치가 편향돼 공차 경계에서 PASS/NG 가 조용히 흔들릴 수 있는 결함. Action_FAIMeasurement.cs 두 지점(ApplyDatumLights 직후 datum grab 전, ApplyShotLights 로 Shot 조명 복귀 직후 EStep.Grab 전)에 LightHandler.Handle.WaitForPendingWrites() 배선 — 수동 grab 경로와 동일 패턴."
    )]
    [Version(
        Number = "1.6.2.0",
        Date = "2026-07-16",
        Change = "일괄 엑셀 Export 가 항상 실패하던 결함 수정 — ClosedXML(SixLabors.Fonts 경유) 이 요구하는 BCL 폴리필 어셈블리 4단 연쇄 불일치가 원인. App.config 에 System.Numerics.Vectors/System.Buffers/System.ValueTuple/Microsoft.Bcl.HashCode 바인딩 리다이렉트 추가 + 프로젝트에 아예 누락돼 있던 Microsoft.Bcl.HashCode 1.1.1 패키지 정식 설치(서명 검증). 실패 재현용 별도 exe 로 실제 exe.config 조건에서 단계별 재현→수정→xlsx 생성 확인. (에러 로그가 ex.Message 만 남기고 InnerException 을 버려 진단이 지연됐음 — 로그 개선은 후속.) " +
                 "검사Grab tact 개선 — CXP 13376x9528(~1.27억 픽셀) 원본을 PNG(DEFLATE 압축)로 저장하던 것이 병목이라 bmp(무압축, 무손실 유지)로 전환. 조명대기+grab/저장 구간별 소요시간 Trace 로깅 추가. 실측 총 ~600ms(조명대기+grab ~290ms, 저장 ~320ms). 실제 검사(RUN) 저장 경로(CaptureImageSaveService)는 원래부터 별도 워커 스레드+JPEG 라 무관함을 코드로 확인(무변경). " +
                 "ArcLineIntersectDistance(I9/I10) 측정 재정의 — 기존은 측정축=우 교점 col, 수직축=두 교점 Row 평균이라 좌 교점이 사실상 무의미했고 X축 부호가 반대(우측인데 음수)로 나왔다. 사용자 확정 정의로 변경: 좌·우 교점을 잇는 직선(L_cross)과 datum 기준선(L_datum, 휜 각도 GetDatumAxisLine 반영)의 교차점 P 를 intersection_ll(TryIntersectLines)로 구하고, 최종 측정값 = P 와 우측 교점 사이의 거리(오른쪽=양수). 좌 교점이 L_cross 기울기→P 위치→세그먼트 길이에 실제 기여. IntersectionPointSelection(Far/Close) 폐기. 오버레이에 L_cross/교차점 P/거리선(P→우교점) 표시해 시각 검증 가능. 실측 5.041(nominal 5.053, 부호 + 정상)."
    )]
    [Version(
        Number = "1.6.3.0",
        Date = "2026-07-16",
        Change = "리스크 점검(코드 전수 스캔 후 재검증)에서 확인된 '조용한 오검' 계열 결함 8건 수정 — 전부 로컬 가드/로그 추가 수준의 저위험 변경. " +
                 "① DatumRef 참조 불일치(오타/개명/삭제)가 IsDatumFailed 게이트를 우회해 identity(무보정)로 조용히 측정되던 결함 — DatumPhase 는 실존 DatumConfigs 만 순회하므로 없는 이름은 검출 시도조차 안 돼 _failedDatums 에 들어가지 않았다. InspectionSequence.IsDatumRefUnresolvable 신설 + Measure 루프 게이트 추가로 NG 승격(SkipReason.DATUM_REF_MISSING 신설). " +
                 "② 미교시(IsConfigured=false) Datum 이 identity pass-through(D-08 설계)로 '성공' 처리되며 로그·DETECT FAIL 배지 어디에도 안 드러나던 결함 — pass-through 자체는 유지(회귀 0)하되 런타임 사용 시 Error 로그 + RuntimeDetectFailed 로 노출. " +
                 "③ 조명 채널명 미매핑(light.ini 재배선 오타/누락) 시 완전 무로그 무동작이던 결함 — TryFindChannel 실패 및 그룹 empty(RebindChannels 가 이름 못 찾은 아이템 제거) 케이스에 경고 로그 추가. 특히 group.Count==0 인데 '성공' 로그+true 를 반환하던 기만적 경로를 false+경고로 교정(반환값 사용 호출부 0건 확인, 회귀 없음). " +
                 "④ Re-anchor 커밋이 검색 ROI 만 이전하고 기준 pose(RefOrigin/RefAngleRad/RefMatch*)는 옛 마스터 값으로 두어, 재티칭 생략 시 런타임 Find 델타가 다시 T 를 산출해 이전이 2회 적용(≈2T)되던 결함 — TransformDatumOwnRois 에서 Ref* 도 동일 T 로 이전(각도 단위 deg/rad 사용처 확인 후 각각 적용). " +
                 "⑤ 레시피 복사 시 <ImageSavePath>\\OfflineInspect\\<구레시피명>\\ 이 박힌 절대경로가 그대로 남아 신규 레시피가 구 물건 이미지로 조용히 검사되던 결함 — RecipeFiles.Copy 후 해당 규약 경로만 초기화(사용자 수동 지정 외부 경로는 보존). " +
                 "⑥ MIL 만 CaptureMode==Streaming 에서 stale 라이브 프레임을 non-null 로 반환해 '검사 grab 성공'으로 위장되던 결함(Hik/Basler 는 null 반환) — null 로 계약 통일 + 경고 로그. 라이브 미리보기는 GetPreviewBitmapSource 별도 경로라 무영향(호출부 확인). " +
                 "⑦ Start 계열 TOCTOU — State 는 시퀀스 스레드가 Command 를 처리(≤5ms tick)해야 Running 이 되므로 UI RUN 과 TCP $TEST 가 겹치면 둘 다 'State!=Idle' 체크를 통과해 RequestPacket/액션범위가 조용히 덮어써졌다(TCP 응답 유실 또는 의도와 다른 액션 실행). StartCore 신설로 락 안에서 State 를 즉시 Running 으로 점유해 원자화하고, RequestPacket 을 점유 성공 후에만 기록. Command 는 소비 후에도 Start 로 유지되는 구조라 가드로 쓸 수 없어 State 점유 방식 채택. OnStart.Invoke 는 락 밖에서 호출(구독자가 Dispatcher 로 UI 접근 — 락 보유 중 UI 대기 시 데드락 위험). " +
                 "⑧ OfflineInspectMode(시스템 전역·영속)가 켜진 채 실물 라인에서 RUN 하면 저장 이미지로 조용히 측정되던 결함 — RUN 트리거 시점 확인 다이얼로그 추가."
    )]
    [Version(
        Number = "1.7.0.0",
        Date = "2026-07-22",
        Change = "부품 하나를 여러 번(높이를 바꿔가며) 나눠서 검사하는 기능을 새로 만들었다. " +
                 "이제 촬영 순서마다 그 순서에 해당하는 자리만 다시 찍고, 관계없는 자리는 다시 안 찍는다(낭비 방지). 어떤 측정 항목은 서로 다른 두 번의 촬영에서 찍은 사진 두 장을 합쳐서 값 하나(예: 거리)를 계산하도록 설정할 수 있다. 기준점(Datum)도 두 번에 나눠 찍을 수 있다. 모든 촬영이 끝난 마지막 순서에서만 합격/불합격을 알려주고, 그 전까지는 '아직 안 끝남'만 알려준다. " +
                 "이번에 같이 고친 것: 사이클이 시작할 때 이전 부품 사진이 안 섞이도록 정리 타이밍 수정, 촬영 순서 목록 정리, 관계없는 자리 재촬영 방지 + 그때 잘못 찍히던 에러 로그 억제, 마지막 순서 판단 로직을 하나로 통일해서 합격/불합격 통보가 중복되지 않도록 함, 기준점 검출이 실패하면 그 즉시 불합격 처리(사용자 승인 받고 켬), 맨 처음 순서(기준점 전용)에서 전체를 다 다시 찍던 낭비 제거. " +
                 "버그 수정: 사진 두 장 중 한 장의 경로가 뒤바뀌던 것 복원, 테스트용(SIMUL) 이미지가 촬영 순서별로 다르게 설정되도록 수정, 손으로 촬영 버튼 눌렀을 때 측정이 안 되던 문제 수정. " +
                 "같은 날 별도로 고친 것: I9/I10 항목의 옵션(Far/Close) 복원, 거리 측정 3개 항목에 여러 점 평균을 적용해서 결과값 흔들림 줄임, 설정 화면에서 안 쓰이는 항목 5개 숨김, 각도 측정 화면에 빠져있던 기준선 표시 추가."
    )]
    [Version(
        Number = "1.7.1.0",
        Date = "2026-07-23",
        Change = "EdgePairDistance 항목 입력을 정해진 값만 고를 수 있게 제한(잘못 입력해도 조용히 0mm로 통과되던 버그 수정), PointToLineDistance 에도 여러 점 평균 적용해서 결과값 흔들림 줄임. " +
                 "측정별 보정값 설정 화면을 다시 켤 수 있게 함 — 기본은 꺼져 있지만, 기존 레시피에 이미 보정값이 들어있으면 불러올 때 자동으로 켜진다(레시피 파일은 손 안 댐). " +
                 "1.7.0.0에서 새로 만든 나눠찍기 기능을 실제 화면 켜놓고 최종 확인 완료 — 마지막 촬영에서 보정값 정상 반영/관계없는 자리 재촬영 0회/합격불합격 통보 정확히 1번, 전부 정상 확인. 확인하다가 발견한 문제 2개 그 자리에서 수정: ① 아직 안 끝난 촬영에서도 에러 로그가 잘못 찍히던 것을 더 넓게 막음, ② 한 자리에 서로 다른 촬영설정이 섞여 있으면 낭비가 생기는 문제를 발견해서 — 저장할 때 그런 설정이면 아예 저장이 안 되고 안내창이 뜨도록 함."
    )]
    [Version(
        Number = "1.7.2.0",
        Date = "2026-07-24",
        Change = "Side 쪽 자동검사가 가끔 엉뚱한(Top 쪽) 샷/카메라/모델 파일을 참조하던 문제 수정 — 이름으로 못 찾을 때 아무 샷이나 잡던 것을, 그 항목이 속한 시퀀스(Top/Side/Bottom) 안에서만 찾도록 범위를 좁혔다. " +
                 "새로 만든 Shot이 프로그램을 껐다 켜기 전까지는 촬영/조명이 안 되던 문제 수정 — Shot을 만드는 즉시 필요한 정보(카메라 이름, 소속)를 채워주고, 같은 줄의 다른 Shot 설정(조명/노출 등)도 이어받게 했다. " +
                 "Device 탭에서 값 입력하고 Enter 키를 누르면 방금 입력한 값이 사라지고 0으로 돌아가던 문제 수정(다른 칸 클릭이나 Tab 키는 원래 문제없었음) — 화면 그리드 라이브러리의 Enter 키 처리 버그를 우회하도록 했다. " +
                 "수동으로 검사이미지를 새로 저장한 뒤 RUN을 눌러도 계속 예전 이미지로 측정되던 문제 수정 — 두 자리에 원인이 있었다: ① 높이를 나눠 찍는 기준점(Datum)의 이전 촬영 기록이 RUN 때 안 지워지고 있었고, ② RUN 자체가 그 나눠찍기 순서에 절대 도달할 수 없는 구조라 기준점이 사실상 다시 검출되지 않고 있었다. 두 자리 다 고쳐서, RUN을 눌러도 항상 저장된 이미지를 새로 읽어 검사하도록 했다. " +
                 "Side 카메라(MIL/CXP 라인)의 노출(Exposure)/게인(Gain) 값을 실제 하드웨어에 반영하는 기능 신규 추가 — 이전엔 화면에서 값을 바꿔도 카메라에 실제로 전달되지 않았다. " +
                 "기준점(Datum) 검출 항목에 노이즈 제거 필터를 새로 추가 — 값을 넣으면(기본은 꺼짐) 에지 방향으로만 노이즈를 눌러주고 실제 경계선은 흐려지지 않게 했다. " +
                 "각도 측정 항목에도 보정값 기능 추가 — 기존엔 길이/거리 측정에만 있던 보정값(곱셈)과 별개로, 각도는 고정값을 더하고 빼는 방식(덧셈)으로 새로 만들었다(기본 꺼짐). " +
                 "Shot 복사(Copy/Paste) 시 카메라 이름이 안 복사되던 문제 수정, 화면에서 실제로 안 쓰이는 Z Position/Gamma 항목 숨김, 데이터 저장 기본 경로들을 D:\\Data 아래로 정리."
    )]
    [Version(
        Number = "1.7.3.0",
        Date = "2026-07-27",
        Change = "정렬(Align) 카메라가 실제로 촬영(Grab)을 시도하면 프로그램이 통째로 멈추던(크래시) 문제를 찾아서 고쳤다 — 카메라 설정(노출/트리거 방식/네트워크 패킷 크기 등)은 전부 정상이었고, 실제 원인은 촬영 함수 이름이 내부적으로 겹쳐서 자기 자신을 끝없이 반복 호출하던 코드 버그였다. 이 버그 때문에 정렬 카메라의 촬영 기능은 이 기능이 생긴 이후 실 하드웨어로는 한 번도 성공한 적이 없었던 것으로 확인됨. " +
                 "이보다 며칠 앞서 먼저 고쳤던 것: 정렬 카메라 연결(Connect)이 실제 카메라가 있어도 항상 실패하던 문제(장치 검색 방식 오류), 연결은 됐는데 촬영 시도 자체가 조용히 안 되고 항상 대체 이미지로 넘어가던 문제(연결 상태 값이 안 채워지고 있었음). " +
                 "라이브(Live, 연속 촬영) 모드 — 화면이 계속 갱신되도록 새로 구현(이전엔 버튼만 있고 실제 화면 갱신은 없었음), 버튼 글자로 켜짐/꺼짐(Live On/Live Off) 표시, 한 번 촬영(Grab)한 뒤 라이브를 켜면 실패하던 문제 수정, 촬영과 라이브를 동시에 못 누르게 상호 잠금 추가."
    )]
    [Version(
        Number = "1.7.4.0",
        Date = "2026-07-29",
        Change = "높이를 나눠 찍는 검사(크로스-Z)에서 사진이 뒤섞이던 문제들을 집중적으로 잡았다. " +
                 "① 한 측정이 두 높이(예: 23번과 24번)를 쓰도록 설정하면, 둘 중 한쪽 높이에서 수동 촬영 버튼이 '트리거 실패'로 아예 거부되던 문제 수정 — 촬영 전 조명을 맞추는 단계가 '한 자리는 높이 하나'라고만 알고 있어서 두 번째 높이를 자기 자리로 인정하지 않았다. " +
                 "② 두 높이로 찍은 사진 중 화면에 보여주고 저장하는 사진이 실제로 그 높이에서 찍은 것과 달랐던 문제 수정. " +
                 "③ 두 높이 중 하나만 찍고 끝났는데도 결과가 '합격'으로 조용히 나오던 문제 수정 — 이제 '아직 안 끝남'으로 명확히 표시되고, 결과 화면과 엑셀에도 그렇게 나온다. " +
                 "④ 두 높이로 찍을 때 가로/세로 사진을 골라 쓰는 기능이 빌드 설정(개발용 옵션)에 따라 켜졌다 꺼졌다 하던 문제 수정 — 이 옵션은 다른 PC와 코드를 합칠 때마다 사라지곤 해서, 현장에서는 설정한 사진 경로를 무시하고 엉뚱한 사진 한 장만 두 번 쓰고 있었다(가로 자리를 세로 사진에서 찾으니 아무것도 못 찾음). 이제 옵션과 무관하게 항상 설정한 사진을 쓴다. " +
                 "RUN 버튼과 일괄 검사가 트리에서 고른 자리가 아니라 엉뚱한 자리를 검사하던 문제 수정 — 자리를 '몇 번째'라는 순번으로 찾고 있어서, 자리를 지우거나 순서를 바꾸면 번호가 밀려 다른 자리가 실행됐다(프로그램을 껐다 켜면 잠깐 정상으로 보여 발견이 늦었다). 이제 순번이 아니라 그 자리 자체를 직접 찾는다. " +
                 "기준점(Datum) 관련 수정 — 검출 실패 메시지에 어느 단계(원/가로선A/가로선B)에서 실패했는지 그대로 표시(기존엔 뭉뚱그린 안내라 어디를 고쳐야 할지 알 수 없었음), 기준 자세를 기록할 때와 실제로 찾을 때의 검색 범위가 서로 달라 각도가 어긋나던 문제 수정, 패턴2 모델 파일을 소속과 무관한 다른 폴더에서 읽어오던 문제 수정(Top/Side/Bottom 이 섞이던 계열). " +
                 "측정 설정 화면에서 '가로축/세로축 티칭 이미지' 칸 2개 숨김 — 메뉴바의 가로/세로 버튼과 검사Grab 으로 이미 자동으로 채워지는 값이라 같은 걸 두 번 설정하게 되어 혼란스러웠다(값과 동작은 그대로, 화면에서만 안 보임)."
    )]
    [Version(
        Number = "1.7.5.0",
        Date = "2026-08-05",
        Change = "MeasurementAlgorithm.TryInspectSingleEdgeInternal 의 strip 측정 루프에서 확정된 HALCON measure handle 누수를 예외-경로 한정으로 수정 — handle 을 닫는 CloseMeasure(handle) 호출이 try/finally 밖의 평문이라, 바로 앞 MeasurePos 호출이 예외를 던지면 실행되지 않고 handle 이 새며, 그 예외는 상위 TryInspectSingleEdge 래퍼의 빈 catch{return false;}에 조용히 삼켜져 겉으로 드러나지 않았다. 형제 구현체(VisionAlgorithmService.AppendStrip, FAIEdgeMeasurementService)와 동일한 try-finally 패턴으로 통일 — MeasurePos 호출과 뒤따르는 결과 누적 블록을 try 안으로, CloseMeasure(handle)을 finally 로 이동. catch 는 추가하지 않아 예외 전파(ROI 전체 실패 처리) 동작과 판정/반환값 로직은 완전히 그대로 보존. 이 메서드는 [Obsolete] 구 액션(TopInspectionAction/BottomInspectionAction) 경로로만 도달하고 표준 운영 경로(RebuildInspectionActions→Action_FAIMeasurement)에서는 실행되지 않지만, TeachingWindow 의 수동 test 버튼에서는 여전히 도달 가능해 확정 누수로 판단해 수정."
    )]
    [Version(
        Number = "1.7.6.0",
        Date = "2026-08-06",
        Change = "카메라(Top/Side/Bottom) 하나만 골라서 RUN 해도 최종 합격/불합격 판정이 다른 카메라 것까지 같이 보고 매겨지던 문제 수정 — 검사 항목 목록이 세 카메라 것 전부 한 곳에 같이 저장돼 있는데, 판정할 때 그중 '지금 돌린 카메라 것'만 골라내는 절차가 빠져 있었다. 그래서 예를 들어 Top만 돌렸을 때 Side/Bottom 쪽 항목이 이번에 측정을 안 해서 비어 있으면 그걸 불합격으로 잘못 읽어, Top 자체는 전부 정상인데도 최종 결과가 불합격(또는 검출실패)으로 뜰 수 있었다. 판정하는 4곳(수동 RUN 판정, 일괄검사 판정, 반복검사 판정, 실제 제어반으로 나가는 통신 응답) 전부에 '지금 돌린 카메라 것만 본다'는 필터를 추가해서 바로잡았다. 필터링 결과 항목이 하나도 안 걸리는 예외 상황(레시피 설정 오류 등)에는 조용히 합격 처리되지 않고 검출실패로 표시되도록 안전장치도 같이 넣었다. 합격/불합격을 가르는 기준 자체는 전혀 안 바꿨다."
    )]
    [Version(
        Number = "1.7.7.0",
        Date = "2026-08-07",
        Change = "배치검사 중 메모리가 계속 쌓이다가 프로그램이 죽던 문제의 진짜 원인을 찾아서 고쳤다 — 카메라 이미지 처리 라이브러리(HALCON)가 윈도우에서 기본으로 쓰는 메모리 관리 방식이, 다 쓴 메모리를 컴퓨터에 돌려주지 않고 계속 쥐고만 있는 게 원인이었다(격리된 테스트 프로그램으로 직접 재현·확인). 이 방식을 윈도우 기본 방식으로 바꿔서, 이제 다 쓴 메모리가 실제로 반환된다. " +
                 "기준점(Datum) 이름을 바꾸면 그 기준점이 쓰던 모델 파일(패턴매칭용)은 예전 이름 그대로 남아서, 검사가 그 파일을 못 찾아 조용히 다 실패하던 문제를 발견해서 고쳤다 — 이제 이름을 바꾸면 파일 이름도 자동으로 같이 바뀐다(레시피를 새로 불러오거나 새 기준점을 만들 때 엉뚱한 파일을 잘못 옮기지 않도록 안전장치도 같이 넣었다). 이미 이 문제로 망가져 있던 SIDE 쪽 기준점 4개는 파일을 직접 바로잡아 복구했고, 옛날에 같은 계열 버그(1.7.2.0/1.7.4.0에서 고침)로 엉뚱한 폴더에 남아있던 죽은 파일들도 정리했다. " +
                 "제어반(PLC)이 촬영 전 신호($PREP)를 보낼 때 '조명 켜라/꺼라'를 매번 같이 보내던 것을 없애고, 대신 한 부품 검사가 완전히 끝나는 순간(합격이든 불합격이든) 프로그램이 알아서 조명을 전부 끄도록 바꿨다 — 제어반은 이제 조명 끄라는 신호를 따로 안 보내도 된다. 고치는 과정에서, Top과 Bottom 카메라를 같은 컴퓨터에서 같이 쓸 때 한쪽이 먼저 끝났다고 조명을 꺼버리면 아직 촬영 중인 다른 쪽까지 어두워질 뻔한 위험을 코드 점검으로 발견해서 미리 막았다(자기가 켰던 조명만 끄도록 범위를 좁힘). 검사 도중 갑자기 중단됐을 때 조명이 안 꺼지고 계속 켜져 있던 결함도 같이 고쳤다."
    )]
    [Version(
        Number = "1.7.8.0",
        Date = "2026-08-07",
        Change = "BottomAlign 정렬 카메라가 연결에 실패하면 화면에 알람 창이 뜨도록 함 — 예전엔 로그만 남고 화면엔 아무 표시가 없어서 카메라가 안 붙어도 사용자가 몰랐다. " +
                 "\"저장된 이미지로 검사하기\" 옵션이 켜진 채로 남아있으면 프로그램을 다시 켤 때마다 자동으로 꺼지도록 함 — 이 옵션이 켜진 채로 실물 라인에서 돌리면 카메라로 새로 안 찍고 예전 저장 이미지로 조용히 검사가 되는 사고가 실제로 있었다. 수동 실행 버튼은 확인창이 뜨지만, 제어반(PLC) 통신으로 들어오는 검사 요청에는 확인창이 없어서 더 위험했다. " +
                 "조명 배선을 실제 배선표에 맞게 코드로 반영 — 링조명+면조명+링조명2를 한 조명컨트롤러(8채널)로, 바조명+동축조명을 다른 조명컨트롤러(5채널)로 묶었다. " +
                 "제어반(PLC)이 검사 상태가 꼬였을 때 프로그램을 껐다 켜지 않고도 초기 상태로 되돌릴 수 있는 새 신호($RESET)를 만듦 — 예전엔 이런 리셋 신호를 보내도 프로그램이 조용히 무시해서 응답조차 안 왔다. " +
                 "제어반(PLC)과 협의해서 통신 방식을 손봄 — 검사 대상(위/아래/옆면)을 글자 대신 숫자로 주고받도록 바꾸고, 얼라인 캘리브레이션 명령(시작/진행/종료/취소)도 글자 대신 숫자로 바꿨다. 검사 결과 통신도 개별 측정값을 전부 보내던 것을 종합 합격/불합격만 보내도록 간단하게 줄였다. 숫자가 아닌 이상한 값이 들어와도 엉뚱하게 해석되지 않도록 안전장치도 같이 넣었다."
    )]
    [Version(
        Number = "1.7.9.0",
        Date = "2026-08-10",
        Change = "한 장 찍는데 8초씩 걸리던 Top(위쪽 카메라) 측정 속도 문제를 고쳤다 — 판정 항목마다 원본 사진을 매번 새로 저장하고 있어서 생긴 낭비였다. 이제 한 번의 촬영당 원본 사진은 딱 한 장만 저장한다(실측 11.7초→4.7초). " +
                 "검사 항목이 아무리 많아도 기준점(Datum)은 한 사이클에 한 번만 찍으면 되는데, 매번 다시 찍고 있던 문제를 고쳤다 — 한 번 찍은 기준점은 그 사이클 안에서는 재사용한다(일괄검사 실측 39.7초→21.7초). " +
                 "조명을 매 촬영마다 채널 전부 다시 켜고 끄던 것을, 이미 원하는 상태면 명령 자체를 다시 안 보내도록 고쳤다 — 실제로 바뀌는 채널만 명령을 보낸다(일괄검사 실측 22.6초→15.4초, 약 32% 단축). 이 과정에서 조명 명령을 동시에 여러 곳(검사 진행 중 vs 외부 신호 vs 화면의 수동 조작)에서 건드리면 서로 충돌해 명령이 조용히 사라질 수 있던 위험도 함께 발견해서 막았다. " +
                 "제어반(PLC)에서 얼라인(위치 보정) 결과를 받을 때, 양수 값 앞에 부호가 안 붙어서 자릿수 파싱이 꼬이던 문제를 고쳤다 — 이제 값이 양수/0/음수 어느 쪽이든 항상 부호(+/-)를 붙여서 보낸다(펨텍 PLC팀 요청 반영). " +
                 "제어반이 보내는 초기화 신호($RESET)가, 검사 시작 버튼이나 화면의 '찾기 테스트(Test Find)' 기능과 정확히 같은 순간에 겹치면 내부 데이터가 깨질 수 있던 위험을 코드 점검으로 찾아서 미리 막았다(실제 사고로 터진 적은 없음, 재검증까지 마침)."
    )]
    [Version(
        Number = "1.7.10.0",
        Date = "2026-08-10",
        Change = "프로그램을 끌 때 Bottom Tray 정렬 카메라의 연결을 안 끊고 있던 문제 수정 — 이제 프로그램 종료 시 그 카메라도 다른 카메라들처럼 정상적으로 연결을 끊는다. " +
                 "자동검사 도중에는 화면 갱신을 건너뛸 수 있는 옵션(기본 꺼짐, 설정 화면에서 켤 수 있음)을 새로 추가 — 문제 있는 항목만 화면에서 확인하면 되는 경우 켜서 쓸 수 있다. " +
                 "화면의 '수동 Z트리거' 버튼(Z모터 없는 지그에서 높이별 촬영을 테스트하는 기능)으로 검사를 돌리면 프로그램이 죽던 문제 수정 — 이 버튼은 실제 제어반(PLC) 통신 없이 테스트용으로 만든 거라 결과를 보낼 상대방 주소가 원래 없는데, 프로그램이 그걸 확인 안 하고 무조건 보내려다 죽고 있었다. 이제 보낼 상대방이 없으면 그냥 건너뛰고 계속 진행한다(실제 제어반 통신은 원래부터 상대방 주소가 항상 있어서 영향 없음)."
    )]
    [Version(
        Number = "1.7.11.0",
        Date = "2026-08-10",
        Change = "판정 항목마다 사진에 표시선을 그려 저장하는 부분이 항목당 300~600ms씩 걸려서 느렸던 걸 고쳤다 — 사진 전체를 화면에 그렸다가 다시 통째로 뽑아내는 방식 대신, 표시선이 들어갈 자리만 직접 칠하는 방식으로 바꿔서 4~6배 빨라졌다(항목당 76~93ms). 그다음으로 남아있던 병목(사진을 압축해서 저장하는 부분, 항목당 약 500ms)도 찾아서 — 압축하는 일꾼을 1명에서 6명으로 늘려 처리 속도를 2.7배 높였다. 두 가지를 합쳐서, 판정 항목이 많은 자리 기준으로 12~13초 걸리던 게 3~4초로 줄었다. " +
                 "Bottom(아래쪽 카메라) 검사에서, 레시피에 아예 배정된 촬영 자리가 없는 순번(예: 23단계 중 특정 한두 단계)에 신호가 오면, 원래는 그냥 '없음'이라고 바로 답하면 되는데 프로그램이 실수로 전체 20여 개 자리를 처음부터 전부 다시 찍고 있었다 — 그 순번 하나 때문에 매번 7.5초씩 두 번(총 15초) 낭비되고 있던 걸 찾아서, 배정된 자리가 없으면 바로 '없음'으로만 답하도록 고쳤다. " +
                 "Bottom 카메라의 좌우 반전 설정을 껐다 — Top 카메라와 같은 방향으로 보이도록 맞췄다(기존 Bottom 레시피는 반전된 상태로 교시되어 있어서 다시 가르쳐야 할 수 있음)."
    )]
    [Version(
        Number = "1.7.12.0",
        Date = "2026-08-10",
        Change = "얼라인 캘리브레이션(피커 위치 맞추기) 진행 상황을 제어반(PLC)에 알려주는 방식을 제어팀 요청대로 바꿨다 — 이전엔 '진행 중' 신호에만 몇 번째 단계인지 숫자가 붙고, '시작/완료/취소' 신호에는 숫자가 안 붙어서 제어반이 신호 종류마다 다르게 처리해야 했다. 이제 모든 신호에 항상 숫자가 붙는다: 시작=0, 진행 중=실제 단계 번호(1~36), 완료=99, 취소=98, 실패=97(어떤 신호든 실패하면 무조건 97). 이렇게 하면 제어반은 신호 종류를 안 가리고 숫자 하나만 보고 지금 상태를 알 수 있다."
    )]
    [Version(
        Number = "1.7.13.0",
        Date = "2026-08-11",
        Change = "제어팀과 확정한 통신 규격서(2D_Vison_Interface_Format)를 코드와 대조해서 어긋난 부분 4곳을 고쳤다. " +
                 "① 얼라인 캘리브레이션이 실패(NG)했을 때 응답의 CMD 값이 규격서는 '어떤 명령이었든 무조건 4'인데, 코드는 방금 보낸 명령 번호를 그대로 돌려주고 있었다 — 실패 시 CMD=4 고정으로 통일. " +
                 "② TEST 신호의 검사대상 번호(Type) 중 '3=2D Bottom'으로 오면 Bottom 카메라로 가야 하는데, 실제로는 Top 카메라로 잘못 연결되고 있었다 — 라우팅 표를 다시 정리해서 0~5번 전부 규격서대로 가도록 고쳤다(0,1,2,4,5번은 원래도 정상이라 동작 그대로, 3번만 실제로 바뀜). " +
                 "③④ 카메라나 조명 쪽에 실제 하드웨어 문제가 생겨서 촬영/측정을 아예 못 했을 때, 그동안은 이걸 그냥 불합격(F)으로 보내고 있었다 — 검사는 정상적으로 했는데 기준에 안 맞아서 떨어진 것과 구분이 안 됐다는 뜻. 이제는 새로운 응답값 E(오류)로 따로 보낸다. 카메라 촬영 실패는 감지 즉시(실측 검사 흐름에서만, 이미지 대체 검사/시뮬레이션 모드는 대상 아님) E로 표시하고, 조명은 연속 3회 이상 통신 실패했을 때 그 순간 검사 중이던 카메라 쪽에 표시한다(다만 조명 쪽은 어떤 조명이 어느 카메라 것인지 정확히 못 나눠서, 문제 생긴 순간 검사 중인 카메라가 여러 대면 전부 같이 E로 나갈 수 있다 — 필요하면 추후 더 정밀하게 나눌 수 있음). " +
                 "그 외에 별개로, 체커보드로 픽셀 캘리브레이션할 때 쓰는 라이브 촬상 버튼이 버벅이던 것도 고쳤다 — 사진을 압축 저장(PNG)하고 다시 불러오는 구간이 화면이 멈춘 채로 돌고 있었는데, 다른 화면에서 이미 썼던 방식대로 압축 안 하는 저장(BMP)으로 바꿔서 저장/재로드 둘 다 빨라졌다."
    )]
    [Version(
        Number = "1.7.14.0",
        Date = "2026-08-11",
        Change = "자동검사가 연속으로 빠르게 돌 때 프로그램이 갑자기 죽던(재현이 어려워 원인을 오래 못 찾았던) 문제의 진짜 원인을 찾아서 고쳤다 — 화면에 방금 찍은 검사 사진을 보여주는 바로 그 순간, 다음 검사가 이미 시작되면서 그 사진을 지워버리는 타이밍이 겹칠 수 있었다. 사진 한 장이 1억 화소가 넘어 화면에 띄우는 데만 수십 밀리초가 걸리는데, 그동안 검사 결과는 제어반(PLC)에 이미 통보되고 다음 검사가 곧바로 시작될 수 있어서 그 짧은 순간에 다음 검사가 끼어들 여지가 있었다. 이 타이밍이 겹치면 프로그램이 죽거나, 최악의 경우 이미 지워진 사진 자리에 남아있던 엉뚱한 값이 화면에 잠깐 표시될 수 있었다(검사 판정 자체에 쓰는 값은 아니라 합격/불합격 결과에는 영향 없음). Top/Bottom/Side 전부 같은 코드를 쓰기 때문에 셋 다 해당되는 문제였다 — 그동안 Side에서 먼저 발견된 건 한 사이클에 찍는 사진 수가 더 많아 이 타이밍이 겹칠 기회가 잦았을 뿐, Top/Bottom도 똑같이 위험한 상태였다. 이제 화면이 사진을 다 쓸 때까지는 다음 검사가 그 사진을 못 지우도록 순서를 확실히 정리했다(사진을 '빌려 쓰고 다 쓰면 반납'하는 방식으로 바꿔서, 화면이 다 보여주기 전엔 아무도 못 지운다). 사진을 옮겨 담는 횟수는 그대로라 검사 속도에는 영향 없다."
    )]
    [Version(
        Number = "1.7.15.0",
        Date = "2026-08-12",
        Change = "티칭(가르치기)이 실패했을 때 왜 실패했는지 알 수 없던 문제를 3단계로 나눠 고쳤다. " +
                 "① 실패 메시지가 영문 원문(templateImage is null 등)으로 그대로 뜨던 것을 한국어 22항목으로 번역해서 보여준다(사전에 없는 문구는 숨기지 않고 원문을 같이 표기). 실패 알림창이 7초 만에 저절로 닫혀 원인을 읽을 새도 없던 것도 7곳 전부 없앴다. 정렬(Align) 상태 표시가 한 번 실패하면 그 뒤에 성공해도 빨간색이 남아있던 것도 고쳤다. " +
                 "② 매칭 점수가 내부에서 계산되고도 버려져서 '얼마나 아슬아슬하게 성공했는지'를 알 수 없던 것을, 성공했을 때도 점수와 등급(좋음●/주의▲/나쁨✕)을 같이 보여주도록 했다(Datum 티칭 완료창, 정렬 티칭, 피커 캘리브레이션 단계). 등급을 가르는 경계값은 현장 데이터를 보고 조정이 필요할 수 있다. " +
                 "③ 제어반(PLC)이 보낸 얼라인 캘리브레이션 요청이 실패하면 로그 파일에만 남고 화면엔 아무것도 안 떠서 현장에서 아무도 모르던 것을, 실패하는 7가지 경우 전부 화면에 표시하도록 했다. 제어반으로 나가는 응답 내용은 전혀 안 바꿨다(코드로 무변경 증명). 이 ③번은 실기에서 3종 명령을 직접 보내 화면 문구와 응답이 모두 기대대로 나오는 것까지 확인 완료. " +
                 "그 외 같은 날 처리한 것: 캡쳐 이미지에 그려 넣는 표시선이 얇아서 잘 안 보이던 것을 1.5배 굵게 조정(화면 실시간 표시는 무변경, 아주 작은 원은 링이 아니라 꽉 찬 원반으로 보일 수 있음), 운영 로그창에 개발자 커밋 태그 문자열이 그대로 찍히던 것 25곳 제거 + 이미 조사가 끝난 개발 진단용 로그 9개 삭제 + 영문으로 남아있던 운영자 메시지 3곳 한국어화. " +
                 "※ ③번을 제외한 나머지 항목은 코드 검증만 마쳤고 실기 육안 확인은 아직 안 했다."
    )]
    [Version(
        Number = "1.7.16.0",
        Date = "2026-08-13",
        Change = "Side(옆면) 지그가 회전 설치돼 상하/좌우가 뒤집혀 촬영되는 상황에 대응할 설정을 새로 만들고, 실제 촬영에까지 연결했다. " +
                 "기준점(Datum) 설정에 좌우반전(MirrorX)/상하반전(MirrorY) 두 항목을 추가했다(기본 꺼짐). 값을 바꾸면 '촬영 방향이 바뀐다 / 이 기준점을 쓰는 다른 측정에도 영향이 간다'는 경고창이 뜨고, 값이 실제로 바뀔 때만 뜬다(레시피를 불러오거나 기준점을 복사할 때는 안 뜸). " +
                 "이 설정이 실제 촬영에 반영되도록 카메라 쪽에 배선했다 — 촬영할 자리가 어느 기준점을 쓰는지 거꾸로 찾아가서 그 기준점의 반전 설정을 따른다. 만약 기준점을 못 찾거나 한 자리가 서로 다른 기준점을 섞어 쓰고 있으면, 반전 없이 그냥 찍고 로그를 남긴다(엉뚱하게 뒤집힌 채로 조용히 검사되는 것 방지). 소프트웨어로 이미지를 뒤집으면 검사 시간이 늘어나기 때문에 카메라 하드웨어 기능으로만 처리한다. " +
                 "기존 레시피에는 이 설정값이 아직 하나도 없어서, 사용자가 직접 켜기 전까지는 동작이 완전히 그대로다(회귀 위험 없음). " +
                 "※ 설정 화면 쪽(항목 노출, 경고창, 재로드 후 값 유지)은 실기 확인 완료. 실제로 이미지가 원하는 방향으로 뒤집혀 나오는지는 Side 카메라 실물이 없어 아직 확인 못 했다(확인 대기). 참고로 경고창의 '재시작해야 적용된다'는 문구는 실제보다 보수적이다 — 촬영할 때마다 방향을 다시 적용하는 구조라 재시작이 꼭 필요하진 않다."
    )]
    [Version(
        Number = "1.7.17.0",
        Date = "2026-08-14",
        Change = "실행 파일로 그냥 돌릴 때가 Visual Studio 디버깅으로 돌릴 때보다 검사가 2~10배 느리던 문제의 진짜 원인을 찾아서 고쳤다 — 윈도우가 프로그램마다 따로 관리하는 '시간 정밀도' 설정이 원인이었다. 윈도우는 기본적으로 시간을 15.6ms 단위로만 쪼개기 때문에, 프로그램이 '5ms만 쉬겠다'고 해도 실제로는 15.6ms를 쉬어버린다. 검사 한 사이클 안에 이런 짧은 대기가 수없이 들어있어서 그게 전부 쌓여 큰 차이가 됐다. 디버깅으로 돌릴 때 빨랐던 건 디버거가 이 정밀도를 1ms로 올려주기 때문이었고, 윈도우10 2004 버전부터 이 설정이 프로그램별로 바뀌어서 옆에서 Visual Studio가 켜져 있어도 우리 프로그램은 혜택을 못 받고 있었다(그래서 '시스템은 이미 1ms인데 왜 느리지'로 보여 원인 파악이 오래 걸렸다). 이제 프로그램이 시작할 때 스스로 1ms를 요청한다 — 윈도우가 공식 제공하는 기능이고 측정 정확도에는 영향이 없다. 실측: 측정 59개짜리 자리가 2,300ms→210ms(약 10배), 제어반 통신 한 사이클 7.2초→2.2초. " +
                 "그런데 이것만으로는 현장에서 불안정했다 — 윈도우11은 프로그램 창이 최소화되거나 다른 창에 완전히 가려지면 이 1ms 요청을 도로 회수해버린다(다른 창으로 덮자마자 즉시 2,300ms로 되돌아가고 프로그램을 재시작해야 회복되는 것을 재현 확인). 현장은 제어반이 통신으로 검사를 시키고 아무도 이 프로그램 창을 보지 않기 때문에 이 회수가 상시 발동할 위험이 있었다. 그래서 윈도우가 이 회수 동작과 함께 공식 제공하는 예외 신청 기능으로, 창이 가려지든 최소화되든 이 프로그램은 회수 대상에서 빠지도록 등록했다(관리자 권한·재부팅·PC별 설정 전부 불필요, 프로그램 배포만으로 적용). 최소화/가림 상태에서 재현 테스트해 속도가 유지되는 것까지 확인했다. 무인 운영 중 CPU 성능이 낮아지는 것도 같은 기능으로 함께 막아뒀다. " +
                 "원인 추적 과정에서 함께 정리한 것: 효과가 없던 '측정 워밍업' 기능 전면 제거(351줄 — 시작할 때 미리 여러 번 측정을 돌려 첫 검사를 데우려던 것인데, 실측 결과 이 문제는 첫 회만 느린 게 아니라 반복해도 계속 느린 현상이라 전제 자체가 틀렸다), 실제로는 아무것도 바꾸지 않던 스레드별 HALCON 캐시 재설정 코드 제거(적용 전 값이 항상 이미 목표값이었음이 자체 로그로 확인됨). 원인 진단용 임시 계측 로그(단계별 소요시간, 타이머 정밀도 실효 상태)는 현장 검증이 끝날 때까지 당분간 남겨둔다. " +
                 "같은 날 별도로 고친 것: 시뮬레이션 모드에서 통신 테스트를 할 때, 기준점을 두 장의 사진으로 찍는 방식이면 사진 경로가 비어 있을 때 곧바로 실패해서 통신 왕복 테스트 자체가 막히던 문제 — 한 장짜리 방식에는 이미 있던 '대체 사진으로 넘어가기'가 두 장짜리 방식에만 빠져 있었다. 이제 두 장짜리도 똑같이 대체 사진을 쓰고, 대체로 넘어갔다는 사실을 로그에 남긴다(정상 티칭 사진으로 검출한 것으로 오해하지 않도록). 이 항목은 사용자 실기 확인 대기 중."
    )]
    [Version(
        Number = "1.7.18.0",
        Date = "2026-08-19",
        Change = "반복검사 데이터를 엑셀로 정리해주는 Cpk(공정능력) 리포트 기능을 새로 만들었다 — 한 시트에는 반복해서 찍은 실측값들을 항목별로 쭉 나열하고, 다른 시트에는 항목마다 최대/최소/평균/표준편차와 Cpk 판정(합격/주의/불합격)을 정리해서 보여준다. 그래프 이미지도 같이 붙는다. 예전엔 방금 돌린 반복검사 결과로만 뽑을 수 있었는데, 특정 기간(며칠부터 며칠까지) 동안 쌓인 검사 기록만 날짜로 골라서 뽑는 기능도 추가했다. " +
                 "이 리포트를 실제로 뽑아보다가 발견한 계산 버그도 고쳤다 — 완전히 똑같은 사진을 여러 번 반복검사하면 Cpk가 정상적으로 '무한대(∞)'로 나와야 하는데, 대신 수조 단위의 말도 안 되는 숫자로 찍히는 경우가 있었다. 컴퓨터가 '완전히 똑같은 값'을 계산할 때도 실제로는 눈에 안 보일 만큼 아주 미세하게 다른 값이 나오는데, 그 미세한 차이를 '0이 아니다'로 잘못 판단해서 생긴 문제였다. 이제 그 정도로 작은 차이는 0으로 보고 정상적으로 무한대(∞)로 표시한다. " +
                 "화면도 여러 곳 손봤다 — 검사 결과 표에서 측정값/판정 칸이 좁아서 잘 안 보이던 걸 넓혔다. 기준점(Datum) 설정 화면에서 실제로 안 쓰는 옛날 항목들(픽셀-um 오프셋, 모터 위치, 프레임 크기 등)을 숨겼다. 화면에서 두 점을 찍으면 그 사이 실제 거리(대각선 + 가로/세로 성분)를 바로 보여주는 '거리측정' 버튼을 새로 만들었고, 기존 mm 보정(Calibrate) 버튼도 같이 손봐서 잰 두 점을 직각삼각형으로 그려주고 각 변에 값을 표시하도록 개선했다. " +
                 "이 화면 기능을 만들다가, 카메라 이미지를 보여주는 창 위에 글자나 안내문을 겹쳐서 띄우면 그 창이 특수하게 그려지는 방식이라 무조건 화면에 안 보이는 구조적인 문제를 발견했다 — 계산 자체는 항상 정상이었는데 결과 문구만 그 창에 가려져 안 보이고 있었다(기존 mm 보정 버튼의 안내문도 같은 이유로 안 보이고 있었음). 이제 결과값은 그 창 안쪽에 직접 그리거나, 창 바깥의 상단 안내줄에 띄운다. " +
                 "자동검사 핵심 코드(Action_FAIMeasurement.cs) 내부 구조도 여러 단계에 걸쳐 정리했다 — 겉으로 보이는 동작(판정 결과, 검사 흐름, 저장되는 값)은 단 하나도 안 바꾸고, 코드 안쪽만 더 읽기 쉽게 나눴다(너무 길던 함수를 작은 단위로 쪼개기, 여기저기 중복돼 있던 코드 통합, 헷갈리게 비슷한 두 판정 함수를 하나로 합치기 등). 매 단계마다 '동작이 정말 그대로인지'를 코드로 직접 대조해서 확인했다."
    )]
    [Version(
        Number = "1.7.19.0",
        Date = "2026-08-20",
        Change = "어제 새로 만든 mm 보정(Calibrate) 버튼을 실제로 써보면서 안내 문구를 보강했다. " +
                 "이 버튼은 값을 입력해서 확인을 누르면 그 즉시 시스템의 보정값이 바뀌는데, 예전엔 아무 경고 없이 조용히 바뀌었다 — 이제는 값을 입력하는 창 자체에 '확인을 누르면 보정값이 바뀐다'는 경고를 먼저 보여주고, 실제로 적용된 뒤에도 '지금 값은 아직 저장 전(메모리에만 반영)이니, 계속 쓰려면 레시피 저장을 눌러라'는 안내를 별도 창으로 띄운다. " +
                 "'거리측정' 버튼(두 점을 찍어서 실제 거리를 바로 보여주는 기능)도 다듬었다 — 대각선 거리는 원래도 mm와 픽셀 값을 같이 보여줬는데, 가로/세로 성분은 mm만 나오던 걸 대각선과 똑같이 mm+픽셀 둘 다 보이도록 맞췄다. 또 아래 검사결과 목록에서 항목을 하나도 안 고른 채로 거리를 재면 mm 환산이 안 되고 픽셀 값만 나오는데, 예전엔 '왜 안 되는지'만 알려주고 '어떻게 하면 되는지'는 안 알려줬다 — 이제는 '아래 목록에서 FAI 항목을 먼저 선택하라'고 바로 알려준다."
    )]
    [Version(
        Number = "1.7.20.0",
        Date = "2026-08-20",
        Change = "PLC 통신 테스트를 실제로 돌려보면서 발견된 프로토콜 결함 2건을 고쳤다. " +
                 "① $PREP 요청 중 '이 z_index엔 원래 조명 켤 Shot이 없는 게 정상'인 자리(기준점 z=0뿐 아니라, 세로/가로 이미지를 나눠 찍는 크로스-Z 기준점의 두 번째 촬영 자리도 포함)를 z=0만 예외로 봐줬던 탓에, Side 검사에서 실제로는 정상인데도 PREP 응답이 FAIL로 나가던 문제를 고쳤다 — 이제 이런 자리는 전부 정상 OK로 응답한다. " +
                 "② 통신 도중 내부적으로 어떤 이유로 응답을 못 만드는 예외 상황에 빠졌을 때, 원래는 대상 종류(Type) 값을 안 채운 채로 응답을 보내던 게 있었다 — 실측으로 '$RESULT:site;;F@'처럼 Type 자리가 비어서 나가는 걸 확인해서, 이 경로도 Type을 항상 채우도록 고쳤다. " +
                 "Side 검사 중 특정 Datum만 반복해서 재검출하느라 반복검사 속도가 느려지던 부분도 손봤다 — 이 Shot이 실제로 쓰는 Datum이 아니면 건너뛰도록 해서 반복검사 시간이 절반 넘게(16.9초→7.8초, 실측) 줄었다. 다만 어느 Shot이 담당인지 레시피에 정확히 안 적혀 있는 Datum은 안전하게 예전처럼 매번 검사하도록 남겨뒀다(잘못 건너뛰면 크로스-Z 이미지가 영영 안 채워져 검사가 멈추는 걸 실측으로 확인했음). " +
                 "$RESET 응답의 이름을 $RESET_ACK에서 $RESET으로 바꿨다(제어팀 요청, 내용 형식은 그대로). " +
                 "설정(Settings) 창에 '원본 이미지 저장 포맷(JPG/BMP)' 선택 옵션을 새로 추가했다 — FAI별로 남기는 원본(origin) 캡쳐 이미지를 JPG 대신 BMP로 저장하고 싶을 때 고를 수 있다(오버레이가 그려진 capture 이미지는 이 설정과 무관하게 그대로 JPG)."
    )]
    [Version(
        Number = "1.7.21.0",
        Date = "2026-08-21",
        Change = "통계 CSV에 '검사구분'(자동/수동) 칸을 하나 추가했다. " +
                 "왜 필요했냐면 — 검사 결과는 날짜별 CSV 파일 하나에 전부 쌓이는데, 셋업하면서 티칭하다가 화면에서 RUN 버튼을 눌러본 결과도 똑같이 그 파일에 들어간다. 그래서 오후에 PLC로 반복성 시험을 100회 돌려도, 오전에 손으로 눌러본 값이 같이 섞여서 통계가 오염된다. " +
                 "예전엔 자재번호가 -1이면 수동이라고 짐작할 수는 있었지만 확실하지 않았다 — PLC가 자재번호를 안 보내거나 숫자가 아닌 값을 보내도 똑같이 -1이 되기 때문에, -1은 '수동'이 아니라 그냥 '자재번호 없음'이라는 뜻이다. " +
                 "이제 CSV 맨 뒤 칸에 '자동'(PLC가 시킨 검사) 또는 '수동'(화면 RUN·일괄검사·반복검사)이 그대로 찍힌다. 엑셀에서 이 칸으로 필터만 걸면 원하는 데이터만 골라서 통계를 낼 수 있다. " +
                 "칸을 맨 뒤에 붙였기 때문에 예전에 쌓아둔 CSV 파일들도 그대로 읽힌다(그 파일들엔 이 칸이 없으므로 '수동'으로 간주한다). " +
                 "실제로 PLC 1사이클과 화면 RUN 1회를 돌려서, 자동 1,100줄 / 수동 25줄로 정확히 나뉘어 기록되는 것까지 확인했다."
    )]
    [Version(
        Number = "1.7.22.0",
        Date = "2026-08-24",
        Change = "제어반(PLC) 없이 수동으로 검사 사이클 하나를 돌려보는 버튼의 이름과 설명을 실제 동작에 맞게 고쳤다 — 이 버튼은 사실 Z축(높이)을 전혀 움직이지 않는데(축 이동 자체가 아직 구현 안 됨), 예전 이름과 안내문은 '축 구현 전까지만 쓰는 임시 버튼'처럼 돼 있어서 오해를 샀다. 실제로는 제어반이 보낼 신호를 사람이 대신 눌러 보내는 진단용 버튼이고, 높이 하나로 끝나는 검사에만 쓸 수 있다(두 높이를 조합해야 하는 검사는 이 버튼으로 재현이 안 된다 — 그건 화면의 RUN 버튼이나 실제 제어반이 해야 한다). 안내 문구를 이에 맞게 고치고, 아무나 못 누르게 ADMIN 권한을 확인하도록 추가했다. " +
                 "검사 항목이 여럿인 자리(예: Side)를 일괄검사로 돌리면, 자리마다 기준점(Datum)을 매번 새로 찾고 있어서 느렸던 걸 고쳤다 — 저장된 사진으로 검사할 때는 어차피 같은 사진에서 같은 걸 찾는 거라, 처음 한 번만 찾고 나머지는 그 결과를 재사용하면 된다. 실측 16초대→5초대로 줄었다(제어반이 실제로 신호를 보내는 자동검사 쪽은 이번에 손대지 않았다 — 그쪽은 매번 다른 사진이 들어오는 구조라 같은 방법을 그대로 쓸 수 없다). " +
                 "제어반과 연결돼 있는 동안 컴퓨터가 계속 버벅이던(가비지컬렉션이 쉴 새 없이 도는) 원인을 찾아서 고쳤다 — 통신이 연결됐는지 확인하는 코드가, 확인할 때마다 이 컴퓨터의 전체 네트워크 연결 목록을 통째로 다시 가져오고 있었다. 그것도 1초에 약 2,000번씩. 이제는 소켓 자신에게 먼저 살아있는지 직접 물어보고, 그래도 의심스러울 때만 예전 방식(전체 목록 조회)으로 재확인한다 — 끊김을 감지하는 판정 로직 자체는 하나도 안 바꿔서, 정상 종료/강제 종료 둘 다 실측으로 재확인했다. " +
                 "부품 위치를 잡을 때 쓰는 2-패턴(멀리 떨어진 두 지점을 이어서 각도를 정밀하게 재는 방식)이 성공했는지 확인할 방법이 없었다 — 실패는 로그에 남는데 성공은 아무 흔적이 없어서, '지금 정밀한 방식으로 돌고 있는지' 알 수가 없었다. 이제 성공도 점수와 함께 로그에 남고, 화면의 '찾기 테스트(Test Find)' 버튼을 누르면 성공/실패 여부와 패턴2 상태를 팝업으로 바로 보여준다(예전엔 성공해도 팝업이 안 떠서 버튼이 반응 없는 것처럼 보였다). 이 김에 정렬(Align) 관련 로그들을 일반 흐름 로그(Trace)에서 알고리즘 로그(Algorithm)로 옮겨서 섞이지 않게 정리했다."
    )]
    [Version(
        Number = "1.7.23.0",
        Date = "2026-08-24",
        Change = "Tray/Bottom Align(이더넷 카메라로 위치를 잡는 기능)에 픽셀 분해능(1픽셀이 실제로 몇 mm인지)을 재는 화면이 지금까지 하나도 없었다 — 코드에 박힌 기본값 하나만 있었고, 실측으로 바꾸려면 설정 화면 숫자칸에 손으로 직접 타이핑하는 것 말고는 방법이 없었다. 기존 검사 화면(MainView)에 이미 있던 두 가지 방식을 그대로 옮겨왔다: ① 체커보드 지그를 놓고 자동으로 격자를 찾아 계산하는 방식, ② 화면에서 두 점을 찍고 실제 거리(mm)를 입력해서 역산하는 방식. Tray/Bottom 둘 다 같은 화면 구성으로 추가했고, 계산된 값은 바로 저장된다(부품별 레시피가 아니라 이 컴퓨터 전체에 적용되는 값이라 별도 저장 버튼이 필요 없다). " +
                 "만들자마자 실사용 확인 중에 버그 하나를 바로 잡았다 — 두 점 찍기 버튼을 눌렀다가 완료하기 전에 다시 누르면, 클릭을 받는 준비가 중복으로 걸려서 캔버스를 한 번만 찍어도 '두 점 사이 거리가 너무 가깝다'는 오류가 바로 떴다(사실은 같은 자리를 두 번 잡은 것으로 계산됐기 때문). 재진입해도 항상 하나만 준비되도록 고쳐서 해결했다."
    )]
    [Version(
        Number = "1.7.24.0",
        Date = "2026-08-25",
        Change = "결과 리뷰어 화면에서 위쪽에 크게 비어 있던 공간을 없앴다 — '이미지 / Overlay'와 '측정 결과' 제목줄이 왼쪽 버튼 묶음(8개)과 같은 줄에 묶여 있어서, 제목 한 줄이면 될 자리가 버튼 높이(약 290픽셀)만큼 통째로 늘어나 있었다. 왼쪽 패널을 위아래 두 칸에 걸치게 바꿔서 제목줄이 제 높이만 차지하도록 했다. 여백과 글자 크기, 측정표 행 높이도 함께 줄여서 한 화면에 보이는 측정 항목이 약 1.6배로 늘었고, 창 기본 크기도 키웠다. " +
                 "측정 행을 클릭하면 그 항목의 이름(F9_P1 등)이 이미지 위에 표시되도록 했다 — 한 검사 항목에 측정이 여러 개 있으면 화면에 선이 여러 개 겹쳐 나오는데, 방금 클릭한 게 어느 선인지 알 방법이 없었다. 제목줄의 '측정명 표시' 체크로 끌 수 있다(기본 켜짐). 색깔 판정에 쓰이는 기존 식별자는 건드리지 않고 이름 전용 칸을 새로 만들어서, 판정 로직에는 영향이 없다. 예전에 저장된 결과 파일에는 이 정보가 없어 이름만 안 뜨고 나머지는 그대로 보인다. " +
                 "이 기능을 넣으면서 생긴 문제 두 개를 바로 잡았다: ① 리뷰어 창을 열 때마다 오류가 나던 것 — 새로 넣은 체크박스가 화면 만드는 순서상 이미지 창보다 먼저 생기는데, 켜짐 초기값이 그 순간 신호를 보내 아직 없는 이미지 창을 건드렸다. ② 이름이 두 번씩 표시되던 것 — 측정 하나가 선을 여러 개(에지선·거리선) 그리는데 선마다 이름을 붙여서 겹쳐 보였다. 화면을 그릴 때 한 번만 쓰도록 고쳤다. " +
                 "조사만 하고 아직 안 고친 것 2건(다음 작업 대상): ① 시뮬레이션 모드에서 제어반 자동검사를 돌리면 기준점을 못 찾아 측정값·표시선·통계가 전부 비어서 나온다. 두 높이를 조합하는 기준점은 세로 사진이 따로 필요한데, 시뮬에는 카메라가 없어 가로 사진을 두 번 읽기 때문이다(화면의 RUN 버튼은 저장된 두 장을 제대로 읽어서 정상, 실제 장비도 정상 — 시뮬+자동 조합에서만 발생). ② 제어반이 응답을 받고 22밀리초 만에 다음 명령을 보내면 아직 정리가 안 끝나 거부되고, 그 거부가 최종 불합격으로 나가 사이클이 중간에 끊긴다."
    )]
    [Version(
        Number = "1.7.25.0",
        Date = "2026-08-26",
        Change = "옆면(SIDE) 검사를 지그 4개로 쪼갰다 — 예전에는 지그 4개가 한 덩어리로 묶여 있어서, 네 개를 다 찍고 나서야 합격/불합격이 딱 한 번 나왔다. 그래서 1번 지그만 불량이어도 어느 지그가 문제인지 알 수 없었고, 이미 불량이 확정된 뒤에도 남은 지그를 끝까지 다 찍었다. 이제 지그마다 따로 도는 검사(SIDE_1~4)로 나눠서, 지그마다 자기 판정이 따로 나간다. 제어반은 Type 값 2/3/4/5 로 어느 지그를 검사할지 지정하고, 검사 위치 번호(z)는 지그마다 0부터 새로 시작한다(SIDE_1 은 0~2, SIDE_2 는 0~3, SIDE_3 은 0~4, SIDE_4 는 0~3). 중간 위치에서는 '진행중(B)' 을 보내고 그 지그의 마지막 위치에서만 합격/불합격이 나간다. " +
                 "준비 명령($PREP)에 '어느 대상인지' 칸을 새로 넣었다 — 예전에는 위치 번호만 보냈기 때문에, 지그마다 위치 번호가 0부터 겹치면 누구를 준비하라는 건지 구분할 방법이 없었다. 이제 $PREP:번호,대상,위치 세 칸으로 받고, 응답도 대상 값을 그대로 돌려준다($PREP_ACK:번호,대상,위치,OK 또는 FAIL). 칸 수가 안 맞거나 모르는 대상이 오면 응답을 안 보내고 멈추는 게 아니라 반드시 FAIL 로 회신한다 — 응답이 없으면 제어반이 무한정 기다려 라인이 서기 때문이다. 여기서 FAIL 은 '조명 세팅에 실패했다' 는 뜻 하나로만 쓴다(그 위치에 검사 항목이 있는지 없는지는 응답에 반영하지 않는다). " +
                 "조명을 켜고 끄는 범위를 '자기 지그 것' 으로 한정했다 — 지그 4개가 같은 조명 채널 이름을 공유하기 때문에, 그대로 두면 1번 지그가 끝나면서 끄는 동작이 2번 지그가 쓰고 있는 조명까지 꺼버릴 수 있었다. 이제 켤 때도 끌 때도 자기가 소유한 채널만 건드리고, 아직 검사 중인 옆 지그의 채널은 건드리지 않는다. " +
                 "자기 범위를 벗어난 위치 번호가 들어와도 합격이 나가던 위험을 막았다 — 예전에는 응답 단계에서 걸러졌지만, 위 FAIL 정의를 바꾸면서 그 방어가 사라졌다. 이제 자기 최대 위치보다 큰 번호가 오면 측정 0건인 채로 최종 판정을 내지 않고 '진행중' 으로만 응답하고 오류 로그를 남긴다. " +
                 "레시피(main.ini)도 함께 옮겼다 — 촬영 8개와 기준점 4개의 소속을 SIDE 에서 SIDE_1~4 로 재배정했다. 티칭해 둔 패턴 파일(.shm)은 옮기지 않고 기존 SIDE 폴더를 계속 쓰도록 이름을 정규화해서, 재티칭 없이 그대로 쓴다. 옮기기 전 레시피로 저장해도 기존 기준점 4개(유일본)가 지워지지 않도록 보존 장치를 넣었다."
    )]
    [Version(
        Number = "1.7.26.0",
        Date = "2026-08-27",
        Change = "정렬(Align)이 틀어졌을 때 비전 탓인지 피커 탓인지 갈라낼 수 있게 증거를 남기기 시작했다 — 예전에는 정렬 결과 수치(보정값)만 로그에 찍고 버렸기 때문에, 나중에 '정렬이 잘못됐다' 는 말이 나오면 비전 쪽에서 방어할 근거가 전혀 없었다. 이제 두 지점에서 재서 기록한다. " +
                 "① 비전 계산이 맞았나 — 정렬이 낸 보정값대로 부품을 옮겼다고 가정한 사진을 실제로 만들어서, 그 사진에서 패턴을 다시 찾아본다. 제대로 계산했다면 이때 남는 어긋남이 0 에 가까워야 한다. 이 값을 매 정렬마다(합격이든 불합격이든) 남긴다. 분쟁은 나중에 생기는데 '그 건은 합격이라 안 남겼습니다' 는 방어가 안 되기 때문이다. " +
                 "② 실제로 어디 놓였나 — 검사할 때 기준점을 찾으면서 이미 매번 원점 좌표를 계산하고 있었는데 그동안 쓰고 버렸다. 그걸 자재번호와 함께 저장만 한다. 카메라를 더 달지도, 검사 시간이 늘지도 않는다. 옆면은 지그 4개(SIDE_1~4)가 따로 집계돼서 어느 지그가 유독 흔들리는지 자체가 정보가 된다. " +
                 "읽는 법은 하나뿐이다 — ①부터 본다. ①이 어긋나 있으면 비전 문제, ①은 정상인데 ②가 튀면 피커 문제다. 결과 리뷰어에 [Align 정합 조회] 버튼을 넣어 자재번호 하나로 두 값을 나란히 보고 최근 N개 평균·최대 추세도 볼 수 있게 했다. " +
                 "판정 기준(몇 mm 를 벗어남으로 볼지)은 이번에 넣지 않았다 — 실제 산포를 모르는 상태에서 기준을 잡으면 잘못 잡았을 때 멀쩡한 제품을 버린다. 지금은 숫자만 보여주고, 데이터가 쌓인 뒤 설정에서 채우면 그때부터 판정이 나온다. " +
                 "불합격 건은 보정한 사진도 파일로 남긴다(합격 건은 안 남긴다 — 예전에 이미지 저장으로 메모리가 58GB 까지 불어난 사고가 있어서 꼭 필요한 것만 남긴다). 저장이 밀리는 상황에서는 사진을 포기하고 숫자만 남긴다. 사진 때문에 제어반 응답이 늦어져 라인이 서는 쪽이 더 큰 손해이기 때문이다. " +
                 "기존 검사 판정·제어반 응답·통계/CPK 파일은 한 줄도 건드리지 않았다(전체 변경이 삭제 1줄 = 클래스 선언 한 단어뿐). " +
                 "확인되지 않는 한계도 문서로 남겼다 — 옆면은 측면에서 찍기 때문에 앞뒤(깊이) 방향은 검증되지 않고 초점만 흐려진다. 그래서 '② 정상 = 잘 놓였다' 로 읽으면 안 된다."
    )]
    [Version(
        Number = "1.7.27.0",
        Date = "2026-08-28",
        Change = "패턴 모델을 만들 때 방해되는 부분을 붓으로 칠해 지울 수 있게 했다 — 티칭용 ROI 안에 항상 같이 잡히는 " +
                 "얼룩이나 옆 부품 같은 것이 있으면 그것까지 모델에 들어가 매칭이 흔들렸다. 이제 그 부분만 칠해서 빼고 모델을 만든다. " +
                 "칠한 자국은 파일로 따로 보관해 다시 티칭할 때 그대로 살아난다. 이 기능은 기본이 꺼짐이라 켜지 않으면 예전과 똑같이 동작한다. " +
                 "티칭 화면도 손봤다 — 그린 ROI 가 바로 사라지지 않고 이름표와 함께 남고, 각도 범위와 최소 점수를 화면에서 직접 넣을 수 있으며(값을 바꾸면 물어본다), " +
                 "화면 가운데 십자선, 마우스 위치의 좌표와 밝기, 두 점 사이 거리 재기, 지금 어느 면을 보고 있는지 표시를 추가했다. " +
                 "캘리브레이션에 쓰는 각도 간격은 검사용 각도 범위와 따로 두었다(10/20/30 선택) — 둘이 같은 값을 쓰다 보니 한쪽을 고치면 다른 쪽이 망가졌다. " +

                 "위치 맞추기(Align) 검증 기록을 실제로 쓸 수 있게 다듬었다. 화면에서 검사를 눌러도 기록이 남게 했다 — " +
                 "예전에는 제어반이 시켰을 때만 남아서, 정작 기준을 정해야 할 셋업 기간에는 데이터가 하나도 안 쌓였다. " +
                 "검증에 걸리는 시간을 127ms 에서 20ms 로 줄였다(6배). 이 계산이 제어반에 답을 보내기 직전에 돌기 때문에 그만큼 설비가 서 있었다. " +
                 "보정이 맞았다면 무늬가 어디에 어떤 각도로 있을지 이미 알고 있는데도 사진 전체를 모든 각도로 뒤지고 있었다 — 그 근처만 보게 바꿨다. " +
                 "못 찾으면 예전 방식으로 한 번 더 찾으므로 숫자를 잃지 않는다. 결과값은 소수점까지 바뀌지 않았다. " +

                 "기록이 사라지던 문제 세 가지를 막았다 — 누가 기록 파일을 엑셀로 열어두면 그 사이 기록이 통째로 버려졌고(로그만 남기고 끝났다), " +
                 "임시로 받아둔 기록이 중복으로 합쳐질 수 있었고, 자정을 넘기면 전날 임시 기록이 영영 합쳐지지 않았다. " +
                 "이제 못 쓰면 옆 파일에 받아두었다가 잠금이 풀리면 자동으로 합치고, 합치기 전에 이름부터 바꿔 중복을 원천 차단한다. " +

                 "부품이 놓인 위치 기록에서 mm 환산이 안 되던 것도 고쳤다 — 촬영 위치를 찾는 방법이 실제 레시피와 맞지 않아 해상도가 늘 0 이었고, " +
                 "고치는 과정에서 캘리브레이션을 안 한 값(1)을 주워 편차가 400배로 부풀 뻔했다. 각도만 재는 자리는 해상도가 필요 없어 캘을 안 하는 것이 정상이라, " +
                 "그런 자리는 걸러내고 같은 카메라의 다른 자리에서 값을 빌려온다. 그래도 없으면 0 을 넣어 '환산 불가' 로 표시한다 — 틀린 mm 를 적느니 모른다고 적는 편이 낫다. " +

                 "판정 기준은 여전히 넣지 않았다(0 = 판정 안 함). 실제 산포를 모르는 상태에서 기준부터 정하면 멀쩡한 제품을 버린다. " +
                 "현장에서 데이터가 쌓인 뒤 설정에 숫자를 넣으면 그때부터 판정이 나온다. " +
                 "이번 작업으로 기존 검사·측정·제어반 응답 로직은 바뀌지 않았다."
    )]
    [Version(
        Number = "1.7.28.0",
        Date = "2026-08-31",
        Change = "제어반과 카메라 사이에서 방향(왼쪽/오른쪽, 회전 방향)이 서로 반대로 잡힐 수 있는 자리에 " +
                 "숫자 하나로 뒤집을 수 있는 조절 값을 넣었다 — Bottom 은 카메라가 아래에서 위로 올려다보는 구조라 " +
                 "화면이 거울처럼 좌우가 바뀌어 보일 수 있고, Tray 는 설계도상 왼쪽이 +인데 계산은 오른쪽 기준으로 하고 있었다. " +
                 "지금은 전부 '안 뒤집음'으로 맞춰뒀다 — 현재 동작은 이전과 완전히 같다. " +
                 "실제로 뒤집혀 있는지는 카메라가 어느 방향을 보고 달렸는지에 달려 있어 화면으로만 봐서는 알 수 없고, " +
                 "현장에서 부품을 한쪽으로 옮겨보고 화면 값의 방향이 맞는지 확인해야 한다. 확인되면 그 숫자만 바꾸면 되고, " +
                 "다른 코드는 손댈 필요가 없다. " +
                 "왼쪽/오른쪽 방향을 뒤집으면 회전 방향도 함께 뒤집힐 수 있어, 그 둘을 묶어서 같이 확인하도록 표시해 두었다 " +
                 "— 하나만 고치면 부품이 조금 돌아갔을 때는 멀쩡해 보이다가 많이 돌아갔을 때만 틀어져서 나중에 발견하기 어렵다."
    )]
    [Version(
        Number = "1.7.29.0",
        Date = "2026-09-01",
        Change = "검사 화면에서 트리의 항목을 고르면, 라이브 영상도 그 항목이 실제 검사 때 쓰는 좌우/상하 반전 상태로 " +
                 "따라 바뀌게 했다 — 예전에는 라이브는 항상 원본 방향으로만 보여서, 반전을 켜둔 항목을 티칭할 때 " +
                 "화면에서 보이는 방향과 실제로 찍히는 방향이 달랐다. 이제 보이는 그대로 찍힌다. " +

                 "정렬(Align) 화면에도 손볼 것들을 정리했다. 지금 보고 있는 화면을 파일로 저장하는 버튼을 Tray/Bottom 양쪽에 넣었다 — " +
                 "현장에서 이상한 장면을 만났을 때 그 자리에서 남겨야 나중에 원인을 찾을 수 있다. " +
                 "피커 중심을 찾는 작업은 예전에는 카메라가 붙어 있어야만 되던 것을, 저장해둔 이미지로도 할 수 있게 바꿨다. " +
                 "피커 중심 계산 결과에 '얼마나 잘 맞았는지'를 숫자로 같이 보여준다 — " +
                 "예전에는 중심 좌표만 나와서 그 값이 믿을 만한지 판단할 근거가 없었다. " +
                 "패턴을 찾을 때 요구하는 최소 점수도 설정에서 바꿀 수 있게 했다(기본 0.5). 조명이나 부품 상태에 따라 " +
                 "너무 엄격하면 못 찾고 너무 느슨하면 엉뚱한 걸 찾는데, 그동안은 코드를 고쳐야만 조절할 수 있었다. " +
                 "정렬 카메라가 연결되지 않았을 때 뜨는 알림도 Tray 인지 Bottom 인지 구분해 표시하게 했다."
    )]
    [Version(
        Number = "1.7.30.0",
        Date = "2026-09-02",
        Change = "정렬(Align) 화면에서 조명이 언제 켜지고 꺼질지를 정리했다. 예전에는 촬영 버튼을 누를 때만 조명을 맞추고 " +
                 "그 뒤로는 아무도 끄지 않아서, 한 번 찍고 나면 조명이 계속 켜진 채로 남아 있었다. " +

                 "라이브(연속 영상)를 켜면 이제 촬영할 때와 똑같은 조명이 함께 켜진다 — 화면의 동축 조명 체크와 밝기 설정을 " +
                 "그대로 따르므로, 라이브로 보이는 밝기와 실제로 찍히는 밝기가 같아졌다. 라이브를 끄면 조명도 같이 꺼진다. " +
                 "Tray 화면과 Bottom 화면 모두 동일하게 적용했다. " +

                 "촬영 버튼으로 한 장 찍은 뒤에도 정해둔 시간이 지나면 조명이 저절로 꺼지게 했다. 대기 시간은 설정에서 " +
                 "밀리초 단위로 바꿀 수 있고(0 으로 두면 자동으로 끄지 않음), 연달아 찍으면 마지막으로 찍은 시점을 기준으로 " +
                 "다시 계산한다. 촬영이 실패하거나 오류가 나도 조명은 똑같이 꺼진다 — 그런 경우가 오히려 조명이 켜진 걸 " +
                 "잊기 쉬운 상황이라 빠짐없이 끄도록 했다. 촬영 직후 라이브를 켜면 예약해둔 소등이 라이브 도중에 " +
                 "조명을 꺼버리지 않도록 예약을 취소한다. " +

                 "주의 : 이미 쓰던 장비에서는 설정 파일에 이 항목이 없어 처음에는 자동 소등이 꺼진 상태(0)로 시작한다. " +
                 "설정 창에서 원하는 시간을 한 번 넣고 저장해야 기능이 동작한다. " +

                 "이번 변경은 정렬 화면의 수동 촬영/라이브 버튼에만 해당하며, 자동 검사 사이클과 티칭 과정의 조명 동작은 " +
                 "그대로 두었다."
    )]
    [Version(
        Number = "1.7.31.0",
        Date = "2026-09-02",
        Change = "이더넷 정렬 카메라(BottomAlign/TrayAlign)의 화면 좌우/상하 반전이 카메라 쪽에 설정해 놔도 계속 풀리던 문제를 고쳤다. " +
                 "원인: 프로그램이 카메라에 연결할 때마다 반전값을 '끔'으로 다시 써 넣고 있었다. 정렬 카메라는 연결 코드가 반전을 " +
                 "항상 끔으로 넘기게 되어 있어서, MVS 같은 카메라 전용 프로그램으로 반전을 켜 두어도 연결하는 순간 원래대로 돌아갔다. " +
                 "이제 프로그램이 반전값을 건드리지 않으므로, 카메라에 저장해 둔 설정이 그대로 유지된다 — 반전이 필요하면 카메라 쪽에서 켜면 된다. " +
                 "검사 카메라(Top/Bottom/Side)는 다른 종류(CXP)라 이 코드를 쓰지 않으므로 영향이 없다."
    )]
    public static class VersionDefine
    {
        //260710 hbk AssemblyVersion 어트리뷰트 인자는 컴파일 타임 상수여야 하므로 반드시 const (static readonly 사용 시 CS0182)
        public const string VERSION = "1.7.31.0";
        public const string BUILD_DATE = "2026-09-02";
    }
}
